async fn test_lifecycle_poll_interval_is_relaxed_and_event_driven() {
    assert!(
        LIFECYCLE_POLL_INTERVAL >= Duration::from_millis(250),
        "Lifecycle watcher poll interval must be relaxed (>= 250ms), got {:?}",
